mapper.select:
SELECT

FROM class_group cg
JOIN campus cp ON cp.id = cg.campus_id
LEFT JOIN course c ON c.id = cg.course_id
LEFT JOIN staff t ON t.id = cg.teacher_id


  ORDER BY cg.name ${sortOrder}
  ORDER BY cg.enrolled_count ${sortOrder}
  ORDER BY cg.start_date ${sortOrder}
  ORDER BY cg.created_at DESC, cg.id DESC
